
import { defineStore } from 'pinia';

export const useRequstionListStore = defineStore({
  id: 'requstionList',
  state: () => ({
    GetRequstionList: []
  }),
  getters: {
    getRequstionList: (state) => state.GetRequstionList
  },
  actions: {

    setRequstionList(list) {
      this.GetRequstionList.push(list);
    },
    deleteRequstionList(index) {
      this.GetRequstionList.splice(index, 1);
    },
    setRequstionItemQuantity(item,index) {
      let TotalQuantity = item.AvailableItems;
      if (parseInt(item.RequestQuantity) > item.AvailableItems) {

        this.GetRequstionList.forEach(ele => {
          if (ele.AssetCatalogueId == item.AssetCatalogueId) {
            ele.RequestQuantity = ele.AvailableItems;
            item.RequestQuantity = item.AvailableItems;

          } else {
            ele.RequestQuantity = item.RequestQuantity
          }
        })
      }
      else {

        this.GetRequstionList.forEach((ele, indx) => {
          if (indx === index) {
            ele.RequestQuantity = item.RequestQuantity;
          }
        });
        
      }
    }

  },
  persist: true,
});
